-- A27: rascunho interno de venda; não representa reserva, proposta, contrato, preço, cobrança ou financeiro.
create table public.subdivision_sale_drafts (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,lot_id uuid not null,buyer_client_id uuid not null,created_by uuid not null references public.identity_subjects(user_id) on delete restrict,created_at timestamptz not null default now(),constraint subdivision_sale_drafts_lot_fk foreign key(lot_id,organization_id) references public.subdivision_lots(id,organization_id) on delete restrict,constraint subdivision_sale_drafts_buyer_fk foreign key(buyer_client_id,organization_id) references public.subdivision_buyer_clients(id,organization_id) on delete restrict,constraint subdivision_sale_drafts_unique unique(organization_id,lot_id,buyer_client_id));
alter table public.subdivision_sale_drafts enable row level security;revoke all on table public.subdivision_sale_drafts from public,anon,authenticated;
comment on table public.subdivision_sale_drafts is 'A27: vínculo interno em rascunho entre lote e cliente comprador; não é reserva, proposta, contrato ou efeito financeiro.';
create or replace function public.subdivision_create_sale_draft(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_lot_id uuid,p_buyer_client_id uuid,p_correlation_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_existing uuid;v_sale_draft_id uuid;begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);select target_id into v_existing from public.admin_audit_events where command_name='subdivision_create_sale_draft' and correlation_id=p_correlation_id and outcome='allowed' order by occurred_at desc limit 1;if v_existing is not null then return v_existing;end if;if not exists(select 1 from public.subdivision_lots where id=p_lot_id and organization_id=p_organization_id) or not exists(select 1 from public.subdivision_buyer_clients where id=p_buyer_client_id and organization_id=p_organization_id) then raise exception using errcode='42501',message='SUBDIVISION_SALE_DRAFT_CONTEXT_DENIED';end if;insert into public.subdivision_sale_drafts(organization_id,lot_id,buyer_client_id,created_by)values(p_organization_id,p_lot_id,p_buyer_client_id,p_actor_user_id)on conflict(organization_id,lot_id,buyer_client_id)do update set created_by=excluded.created_by returning id into v_sale_draft_id;insert into public.admin_audit_events(correlation_id,actor_user_id,organization_id,command_name,outcome,target_type,target_id,payload_redacted)values(p_correlation_id,p_actor_user_id,p_organization_id,'subdivision_create_sale_draft','allowed','subdivision_sale_draft',v_sale_draft_id,jsonb_build_object('module',p_module::text,'purpose_code',trim(p_purpose_code),'sale_draft_linked',true));return v_sale_draft_id;end;$$;
revoke all on function public.subdivision_create_sale_draft(uuid,uuid,public.operating_module,text,uuid,uuid,uuid) from public,anon,authenticated;grant execute on function public.subdivision_create_sale_draft(uuid,uuid,public.operating_module,text,uuid,uuid,uuid) to service_role;
create or replace function public.subdivision_list_sale_drafts(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(sale_draft_id uuid,lot_id uuid,buyer_client_id uuid,created_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select id,lot_id,buyer_client_id,created_at from public.subdivision_sale_drafts where organization_id=p_organization_id order by created_at desc;end;$$;
revoke all on function public.subdivision_list_sale_drafts(uuid,uuid,public.operating_module,text) from public,anon,authenticated;grant execute on function public.subdivision_list_sale_drafts(uuid,uuid,public.operating_module,text) to service_role;
